{
  "schema_version": 5,
  "type": "bugfix",
  "problem": [
    {
      "text": "The wrapper loaded tokenizer.json without explicitly disabling backend truncation. Encoding helpers then consumed the backend's returned IDs directly.",
      "basis": "source",
      "evidence": ["call_a4d49ab8178d4c0ea5d12efb6e4b2552"]
    }
  ],
  "reasoning": [
    {
      "text": "Calling no_truncation() once during construction establishes the policy on the shared backend before vocabulary probes and subsequent encoding, rather than modifying each encoding call.",
      "basis": "source",
      "evidence": ["call_afd71a7732364b75acda464087d0670e", "call_a4d49ab8178d4c0ea5d12efb6e4b2552"]
    }
  ],
  "impact": [
    {
      "text": "For tokenizers loaded with truncation enabled, the intended effect is to preserve input tokens instead of silently shortening backend encodings. This does not itself provide model-context-length enforcement.",
      "basis": "inference",
      "evidence": ["call_afd71a7732364b75acda464087d0670e", "call_a4d49ab8178d4c0ea5d12efb6e4b2552"]
    }
  ],
  "source_notes": [
    {
      "text": "The earlier tokenizer entry describes absence-safe BOS/EOS lookup; those guards remain present and are not modified by this change.",
      "basis": "source",
      "evidence": ["call_a4d49ab8178d4c0ea5d12efb6e4b2552", "call_afd71a7732364b75acda464087d0670e"]
    },
    {
      "text": "Issue #7 reports an undefined native symbol, while issue #15 reports incoherent low-bpw output and discusses quantization regularization. Neither discussion identifies tokenizer truncation as its cause.",
      "basis": "source",
      "evidence": ["call_2711fb87d01a4ff6828eadb2fbc3cc23", "call_d7065e103b1c49aa93010024425f533a"]
    }
  ],
  "limitations": [
    "No backend tokenization or complete initialization was executed; no affected tokenizer artifact or reproduced truncated input was supplied.",
    "A standard-library scalar computation would not validate this external-backend state change, so no substitute numerical test was performed."
  ],
  "links": ["df30645b725b113599d60496a8f94d6f649119ea"],
  "chapters": [
    {
      "id": "loading-tokenization",
      "title": "Disable backend truncation at tokenizer initialization",
      "claims": [
        {
          "text": "Tokenizer.__init__ now calls self.tokenizer.no_truncation() after loading the backend and auxiliary JSON dictionaries, before the BPE space/newline probes. The call is unconditional and adds no wrapper option.",
          "basis": "source",
          "evidence": ["call_afd71a7732364b75acda464087d0670e", "call_a4d49ab8178d4c0ea5d12efb6e4b2552"]
        },
        {
          "text": "encode_special, encode_unspecial and num_tokens all use this same backend. Public encode still adds optional BOS/EOS tokens and left-pads list inputs to the longest encoded sequence; these operations are unchanged.",
          "basis": "source",
          "evidence": ["call_a4d49ab8178d4c0ea5d12efb6e4b2552", "call_afd71a7732364b75acda464087d0670e"]
        },
        {
          "text": "Removing backend shortening favors complete encodings over honoring a serialized truncation policy. Previously capped inputs may consequently produce longer tensors and require length handling by callers.",
          "basis": "inference",
          "evidence": ["call_afd71a7732364b75acda464087d0670e", "call_a4d49ab8178d4c0ea5d12efb6e4b2552"]
        }
      ]
    }
  ],
  "findings": [],
  "summary": "Disable truncation on the shared tokenizer backend during initialization, without changing wrapper encoding or padding logic."
}
